25: // NewFromDirectory returns an instantiated Initrd interface which is is able to
26: // serialize a rootfs from a given directory.
27: func NewFromDirectory(_ context.Context, dir string, opts ...InitrdOption) (Initrd, error) {
28: 	dir = strings.TrimRight(dir, string(filepath.Separator))
29: 	rootfs := directory{
30: 		opts: InitrdOptions{},
31: 		path: dir,
32: 	}
33: 
34: 	for _, opt := range opts {
35: 		if err := opt(&rootfs.opts); err != nil {
36: 			return nil, err
37: 		}
38: 	}
39: 
40: 	if !path.IsAbs(dir) {
41: 		rootfs.path = filepath.Join(rootfs.opts.workdir, dir)
42: 	}
43: 
44: 	fi, err := os.Stat(rootfs.path)
45: 	if err != nil && os.IsNotExist(err) {
46: 		return nil, fmt.Errorf("file does not exist: %s", rootfs.path)
47: 	} else if err != nil {
48: 		return nil, fmt.Errorf("could not check path: %w", err)
49: 	} else if !fi.IsDir() {
50: 		return nil, fmt.Errorf("supplied path is not a directory: %s", rootfs.path)
51: 	}
52: 
53: 	return &rootfs, nil
54: }
