145: 
146: 		if d.Type().IsDir() {
147: 			header := &cpio.Header{
148: 				Name:    internal,
149: 				Mode:    cpio.FileMode(info.Mode().Perm()) | cpio.TypeDir,
150: 				ModTime: info.ModTime(),
151: 				Size:    0, // Directories have size 0 in cpio
152: 			}
153: 
154: 			// Populate platform specific information
155: 			FileInfoToCPIOHeader(info, header)
156: 
157: 			if err := writer.WriteHeader(header); err != nil {
158: 				return fmt.Errorf("could not write CPIO header: %w", err)
159: 			}
160: 			return nil
161: 		}
162: 
163: 		log.G(ctx).
164: 			WithField("file", internal).
165: 			Trace("archiving")
166: 
167: 		var data []byte
168: 		targetLink := ""
169: 		if info.Mode()&os.ModeSymlink != 0 {
170: 			targetLink, err = os.Readlink(path)
171: 			data = []byte(targetLink)
172: 		} else if d.Type().IsRegular() {
173: 			data, err = os.ReadFile(path)
174: 		} else {
175: 			log.G(ctx).Warnf("unsupported file: %s", path)
176: 			return nil
177: 		}
178: 		if err != nil {
179: 			return fmt.Errorf("could not read file: %w", err)
180: 		}
181: 
182: 		header := &cpio.Header{
183: 			Name:    internal,
184: 			Mode:    cpio.FileMode(info.Mode().Perm()),
185: 			ModTime: info.ModTime(),
186: 			Size:    info.Size(),
187: 		}
188: 
189: 		// Populate platform specific information
190: 		FileInfoToCPIOHeader(info, header)
191: 
192: 		switch {
193: 		case info.Mode().IsRegular():
194: 			header.Mode |= cpio.TypeReg
195: 
196: 		case info.Mode()&fs.ModeSymlink != 0:
197: 			header.Mode |= cpio.TypeSymlink
198: 			header.Linkname = targetLink
199: 
200: 		case header.Links > 0:
201: 			header.Size = 0
202: 		}
203: 
204: 		if err := writer.WriteHeader(header); err != nil {
205: 			return fmt.Errorf("writing cpio header for %q: %w", internal, err)
206: 		}
207: 
208: 		if _, err := writer.Write(data); err != nil {
209: 			return fmt.Errorf("could not write CPIO data for %s: %w", internal, err)
210: 		}
211: 
212: 		return nil
213: 	}); err != nil {
214: 		return fmt.Errorf("could not walk output path: %w", err)
215: 	}
216: 
217: 	if initrd.opts.compress {
218: 		if err := compressFiles(initrd.opts.output, writer, f); err != nil {
219: 			return fmt.Errorf("could not compress files: %w", err)
220: 		}
221: 	}
222: 
223: 	return nil
224: }
